(()=>{const qa=(s,r=document)=>[...r.querySelectorAll(s)];const menus=qa("[data-mobile-menu]");const open=document.querySelector("[data-menu-open]");const closers=qa("[data-menu-close]");const set=v=>{menus.forEach(m=>m.hidden=!v);document.body.style.overflow=v?"hidden":""};if(open)open.addEventListener("click",()=>set(true));closers.forEach(el=>el.addEventListener("click",e=>{if(el.tagName==="A"&&el.getAttribute("href")==="#")e.preventDefault();set(false)}));qa("[data-btn-honey],[data-btn-ghost]").forEach(btn=>{btn.addEventListener("mouseenter",()=>btn.classList.add("is-hot"));btn.addEventListener("mouseleave",()=>btn.classList.remove("is-hot"));btn.addEventListener("focus",()=>btn.classList.add("is-hot"));btn.addEventListener("blur",()=>btn.classList.remove("is-hot"))})})();
